      '@media (prefers-reduced-motion:reduce){#' + PORTAL_ID + ' .snb-overlay,#' + PORTAL_ID + ' .snb-sheet{transition:none}#' + PORTAL_ID + ' .snb-spin{animation:none;border-top-color:#111}}';
    document.head.appendChild(style);
